{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 공원 조성 공사가 절반만 끝난 상태에서 이미 조성이 끝난 구역만 따로 점용허가를 내줄 수 있는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 제9조제1호는 점용허가를 할 수 있는 공원으로 ‘도시계획사업 또는 다른 법률에 의하여 공원조성이 완료(일부 조성이 완료된 경우는 완료된 부분을 말한다)된 공원’을 규정하고 있다. 따라서 조성 공사가 절반만 끝난 상태라도 이미 조성이 완료된 부분이 있으면 그 완료된 부분에 대해서는 점용허가 대상이 될 수 있다. 다만 실제 허가 가능 여부는 해당 부분이 위 조항의 요건을 충족하는지, 그리고 법 제24조 등 관련 절차에 따라 공원관리청이 허가 여부를 판단하는 데 달려 있다.",
          "b_ids": "도시공원:제9조, 도시공원:제9조제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
